// FUNCTION: BFME2 0x0037DC36 size=28 name=?update@RecorderClass@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void RecorderClass::update()
{
	if (m_mode == RECORDERMODETYPE_RECORD || m_mode == RECORDERMODETYPE_NONE)
		updateRecord();
	else if (m_mode == RECORDERMODETYPE_PLAYBACK)
		updatePlayback();
}
